-- 0011: FAKE demo crew for the flight-surgeon console and every astronaut screen. Generated by
-- scripts/gen_demo_seed.py (edit the script, not this file). Add-only and safe to re-run (INSERT OR IGNORE).
-- 0008 removed the 0007 demo rows; this re-creates the demo astronaut d001 and surgeon d002 plus more crew.
-- Remove any of them with queries/delete_user.sql and the user_id (all ids are 00000000-0000-4000-8000-00000000d0xx).
-- No 'demo' (Try demo) identity is created here. The only logins are 'dev' identities, which work only with
-- DEV_LOGIN=true on a loopback host (local development): vega@demo.evade.local, ortiz@demo.evade.local, okafor@demo.evade.local.
INSERT OR IGNORE INTO users (user_id,display_name,role,environment,mission_name,mission_start,consent,points,streak_days,last_active,full_name,crew_id,crew_role,mission_length_days) VALUES
('00000000-0000-4000-8000-00000000d001','Demo Astronaut','astronaut','station','Expedition 74',strftime('%Y-%m-%dT%H:%M:%fZ','now','-141 days'),1,0,0,strftime('%Y-%m-%dT%H:%M:%fZ','now','-225 minutes'),'Demo Astronaut','exp-74','Flight Engineer',180),
