UPDATE users SET display_name='Demo Flight Surgeon', full_name='Demo Flight Surgeon', crew_id='exp-74', crew_role='Flight surgeon', mission_name='Expedition 74' WHERE user_id='00000000-0000-4000-8000-00000000d002';
-- 0007's legacy tasks (no task_key) are moved into the past so they do not clutter today's board.
UPDATE tasks SET due_at=strftime('%Y-%m-%dT%H:%M:%fZ','now','-3 days') WHERE user_id='00000000-0000-4000-8000-00000000d001' AND id BETWEEN 900001 AND 900004 AND task_key IS NULL;
