INSERT OR IGNORE INTO journal_entries (client_id,user_id,ts,source,content,ai_summary,sentiment,mood_label,concern_level,analyzed_at,analysis_model) VALUES
('demo-j-d001-0','00000000-0000-4000-8000-00000000d001',strftime('%Y-%m-%dT%H:%M:%fZ','now','-90 minutes'),'text','Woke up foggy after a short sleep. Heart rate was up this morning but settled after breakfast and water.','Short sleep and a fast morning heart rate that settled with rest.',-0.1,'tired','low',strftime('%Y-%m-%dT%H:%M:%fZ','now','-89 minutes'),'demo'),
('demo-j-d001-1','00000000-0000-4000-8000-00000000d001',strftime('%Y-%m-%dT%H:%M:%fZ','now','-1530 minutes'),'voice','Watched the sunrise over the Pacific from the cupola. Missing home a little, but the crew dinner helped.','Positive day with mild homesickness; social time with the crew helped.',0.4,'calm','low',strftime('%Y-%m-%dT%H:%M:%fZ','now','-1529 minutes'),'demo'),
('demo-j-d001-3','00000000-0000-4000-8000-00000000d001',strftime('%Y-%m-%dT%H:%M:%fZ','now','-4410 minutes'),'voice','ARED went well, hit a new squat number. Dinner was the salmon again, which I don''t mind.','Strong workout and steady mood.',0.5,'upbeat','none',strftime('%Y-%m-%dT%H:%M:%fZ','now','-4409 minutes'),'demo'),
('demo-j-d001-6','00000000-0000-4000-8000-00000000d001',strftime('%Y-%m-%dT%H:%M:%fZ','now','-8730 minutes'),'text','Busy day with the plant experiment. Didn''t drink enough water, I noticed the headache in the afternoon.','Productive day; under-hydrated with an afternoon headache.',0.0,'focused','low',strftime('%Y-%m-%dT%H:%M:%fZ','now','-8729 minutes'),'demo'),
('demo-j-d001-10','00000000-0000-4000-8000-00000000d001',strftime('%Y-%m-%dT%H:%M:%fZ','now','-14490 minutes'),'text','Hard week. Feels like the station is getting smaller. Haven''t talked to anyone outside the crew in days.','Isolation and low mood for several days; worth a check-in.',-0.5,'low','moderate',strftime('%Y-%m-%dT%H:%M:%fZ','now','-14489 minutes'),'demo'),
('demo-j-d001-12','00000000-0000-4000-8000-00000000d001',strftime('%Y-%m-%dT%H:%M:%fZ','now','-17370 minutes'),'text','Call with my sister today. It helped more than I expected.','Family call lifted mood after a difficult stretch.',0.3,'relieved','low',strftime('%Y-%m-%dT%H:%M:%fZ','now','-17369 minutes'),'demo'),
('demo-j-d001-18','00000000-0000-4000-8000-00000000d001',strftime('%Y-%m-%dT%H:%M:%fZ','now','-26010 minutes'),'text','Solar particle event drill turned real for a few hours. Sheltered in the lab with the crew, oddly fun.','Calm response to a radiation shelter event.',0.2,'calm','low',strftime('%Y-%m-%dT%H:%M:%fZ','now','-26009 minutes'),'demo'),
('demo-j-d001-25','00000000-0000-4000-8000-00000000d001',strftime('%Y-%m-%dT%H:%M:%fZ','now','-36090 minutes'),'voice','First week back on the full exercise plan. Sore but good.','Back on the full exercise plan; positive.',0.4,'upbeat','none',strftime('%Y-%m-%dT%H:%M:%fZ','now','-36089 minutes'),'demo');
